function spyMonitorDuration(value){const n=Number(value),s=Number.isFinite(n)?Math.max(0,Math.floor(n)):0;if(s<60)return s+'秒';if(s<3600)return Math.floor(s/60)+'分'+(s%60?s%60+'秒':'');return Math.floor(s/3600)+'小时'+(Math.floor(s%3600/60)?Math.floor(s%3600/60)+'分':'');}
