function spyMonitorNativeUsage(c){/* PRIVATE_MONITOR_REAL_USAGE_V1 */if(!privateNativeAppOn())return null;const st=S.couple&&c&&S.couple.cid===c.id?companionState():null,denied=!st||!st.roleAccess||!st.permissions||!st.permissions.screenTime;if(denied)return{usage:[],caption:'真实 iPhone 屏幕使用时间尚未授权给当前角色。'};if(!st.linked||st.demo||!st.screenTimeAvailable||!companionUsageSnapshotFresh(st))return{usage:[],caption:'尚无当天有效的真实 iPhone 时长；点右上角刷新。不会使用小手机内部计时代替。'};const usage=st.screenTimeMode==='per_app'?(st.apps||[]).filter(x=>x&&Number.isFinite(+x.usedSec)&&+x.usedSec>=0).map(x=>({key:'native:'+x.id,name:String(x.name||'iPhone App'),seconds:+x.usedSec,limit:Math.max(0,+x.limitMin||0)*60})).sort((a,b)=>b.seconds-a.seconds):[];return{usage,caption:'真实 iPhone · '+st.usageDay+' · 采集于 '+hm(st.usageGeneratedAt)+'；总使用 '+spyMonitorDuration(st.screenTimeSec)+(st.screenTimeMode==='per_app'?'。':'；系统尚未提供逐 App 明细。')};}
function spyMonitorData(id){if(!spyMonitorAllowed(id))return null;const c=getC(id),d=S.spy&&S.spy[id]||{},account=String(actId()),same=row=>String(row&&(row.accountId||row.acct)||'main')===account,views=(Array.isArray(d.viewLog)?d.viewLog:[]).filter(v=>v&&same(v)).slice().sort((a,b)=>(+b.ts||0)-(+a.ts||0)),today=views.filter(v=>spyDateDay(+v.ts)===todayStr()),au=S.me.appUsage&&S.me.appUsage.date===todayStr()?S.me.appUsage:{},g=S.couple.grant||{},tl=S.couple.timeLimit||{},used=au.used||{},bonus=au.bonus||{},num=n=>Number.isFinite(+n)?Math.max(0,+n):0;
 const usage=(au.date===todayStr()?Object.keys(LOCKABLE):[]).filter(k=>g[k]&&(num(used[k])>0||num(tl[k])>0)).map(k=>({key:k,name:LOCKABLE[k],seconds:num(used[k]),limit:num(tl[k])>0?num(tl[k])*60+num(bonus[k]):0})).sort((a,b)=>b.seconds-a.seconds),watched=String(d.watchedAccount||'main')===account&&Array.isArray(d.watched)?d.watched:[],dy=(S.dy&&Array.isArray(S.dy.liked)?S.dy.liked:[]).filter(v=>v&&same(v)&&v.liked!==false),x=(S.x&&Array.isArray(S.x.tweets)?S.x.tweets:[]).filter(t=>t&&same(t)&&Array.isArray(t.likes)&&t.likes.includes(S.me.name));const nativeUsage=spyMonitorNativeUsage(c);return{c,d,views,today,usage:nativeUsage?nativeUsage.usage:usage,usageCaption:nativeUsage?nativeUsage.caption:'仅包含本应用内已授权的使用记录。',watched,dy,x};}
