async function spyWatchDel(id,i){const data=spyMonitorData(id);if(!data||data.watched[i]==null)return;const row=data.watched[i],rows=data.watched,state=S,account=actId();if(!await uiConfirm('清除这条动态快照？原聊天、点赞和使用记录不会删除。',{yes:'清除',no:'保留',danger:true}))return;const now=spyMonitorData(id);if(S!==state||actId()!==account||!now||now.watched!==rows||!rows.includes(row)){closeModal();toast('记录或账号已变化');return;}rows.splice(rows.indexOf(row),1);save();closeModal();render();}
