function spyChangePwd(id){const c=getC(id);if(!c)return;const el=document.getElementById('spynewpw');const v=(el?el.value:'').trim();
  if(!/^\d{4}$/.test(v)){toast('请输入4位数字密码');return;}
  const sp=getSpy(c);const old=spyPwd(c);
  if(v===String(old)){toast('和原来的密码一样哦');return;}
  sp.pwd=v;save();render();toast('密码已改成 '+v+' 🔒');
  if(c&&!c.blocked)setTimeout(()=>{const cc=getC(id);if(cc&&!cc.blocked)scheduleReply(id,'[系统：你刚发现自己手机的解锁密码被'+S.me.name+'偷偷改掉了！原来的密码进不去了，你并不知道改成了什么。你意识到ta动了你手机、还改了你的密码，心里很复杂。按你人设反应（吃醋/委屈/质问/强势/反过来逼问ta为什么改、是不是不信任你、想查什么），自己决定要不要逼ta把新密码说出来。]');},(60+Math.floor(Math.random()*60))*1000);}
function spySetPhone(id){const c=getC(id);if(!c)return;const el=document.getElementById('spyphone');const v=(el?el.value:'').trim().replace(/\s/g,'');
  if(v&&!/^\d{6,15}$/.test(v)){toast('手机号请填数字');return;}
  getSpy(c).phone=v;save();render();toast(v?('手机号已设为 '+v):'已清空手机号');}
