let _spyBankHidden={};
function spyBankIcon(kind,size){if(kind==='wechat')return '<svg class="sb-wechat-icon" viewBox="0 0 40 36" width="'+(size||34)+'" height="'+(size||34)+'" aria-hidden="true"><path fill="#07c160" d="M2 14C2 7.4 8.4 2 16.2 2s14.2 5.4 14.2 12-6.4 12-14.2 12c-1.8 0-3.6-.3-5.2-.8L5 28l1.5-5.6A11.2 11.2 0 0 1 2 14Z"/><circle cx="11.1" cy="11" r="1.6" fill="#073b28"/><circle cx="21.1" cy="11" r="1.6" fill="#073b28"/><path fill="#fff" stroke="#171818" stroke-width="1.4" d="M15.3 23c0-5.7 5.1-10.3 11.5-10.3S38.3 17.3 38.3 23c0 3.1-1.5 5.8-4 7.7l1.1 4.1-4.8-2.3c-1.2.4-2.5.6-3.8.6-6.4 0-11.5-4.5-11.5-10.1Z"/><circle cx="22.7" cy="20.8" r="1.3" fill="#343a38"/><circle cx="30.8" cy="20.8" r="1.3" fill="#343a38"/></svg>';const paths={eye:'<path d="M2 12q10-14 20 0-10 14-20 0Z"/><circle cx="12" cy="12" r="3"/>',download:'<path d="M12 3v16M6 13l6 6 6-6"/>',chart:'<path d="M5 19v-5m7 5V9m7 10V4"/>',shop:'<path d="M3 4h3l3 11h10l3-8H7M10 20h.01M19 20h.01"/>'};return paths[kind]?'<svg viewBox="0 0 24 24" width="'+(size||22)+'" height="'+(size||22)+'" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[kind]+'</svg>':svgIc(kind,size,'currentColor');}

function spyBankMask(id){_spyBankHidden[id]=!_spyBankHidden[id];render();}
function spyBankRows(id){const d=S.spy&&S.spy[id]||{};return (Array.isArray(d.wallet)?d.wallet:[]).map((w,i)=>({...w,_sourceIndex:i})).sort((a,b)=>(+b.time||0)-(+a.time||0));}
function spyBankBillRows(id,limit){const rows=spyBankRows(id),shown=limit?rows.slice(0,limit):rows;return shown.map(w=>`<div class="sb-bill-row"><i>${spyBankIcon(+w.amount>=0?'chart':'shop',20)}</i><span><b>${esc(w.item||'收支记录')}</b><small>${esc(w.when||w.time&&fmtDT(w.time)||'时间未记录')}</small></span><strong class="${+w.amount>=0?'in':'out'}">${+w.amount>=0?'+':''}${(+w.amount||0).toFixed(2)}</strong></div>`).join('')||'<div class="sb-empty">还没有收支记录</div>';}
function spyBankBills(id){const html=`<h3>银行账单</h3><div class="sb-ledger">${spyBankBillRows(id,0)}</div><button class="btn g" onclick="closeModal()">关闭</button>`;(typeof familyRoleModal==='function'?familyRoleModal:openModal)(html);}
function spyBankTransferIn(id){openChat(id);cTransfer(id);}
function spyBankPanelHTML(id,c,d){const bal=spyBalance(c,d),hidden=!!_spyBankHidden[id];return `<section class="sb-balance"><div class="sb-balance-label">自己的银行余额<button aria-label="${hidden?'显示':'隐藏'}银行余额" onclick="spyBankMask('${id}')">${spyBankIcon('eye',18)}</button></div><div class="sb-balance-value">${hidden?'¥ ••••••':'¥'+bal.toFixed(2)}</div><div class="sb-balance-actions"><button onclick="spyBankTransferIn('${id}')" title="通过微信转账给TA，收款后入账"><i>${spyBankIcon('download',24)}</i><span>转入</span></button><button onclick="spyWxTransferOpen('${id}')"><i>${spyBankIcon('user',24)}</i><span>转给自己</span></button><button onclick="spyBankBills('${id}')"><i>${spyBankIcon('file',24)}</i><span>账单</span></button></div></section><section class="sb-transfer"><i>${spyBankIcon('wechat',36)}</i><span><b>登录微信转给自己</b><small>仅在小手机内模拟，会留下账单痕迹，ta之后可能发现。</small></span><button onclick="spyWxTransferOpen('${id}')">转给自己</button></section><section class="sb-recent"><header><h3>近期收支</h3><button onclick="spyBankBills('${id}')">查看全部 ›</button></header>${spyBankBillRows(id,2)}</section>`;}
function spyBalance(c,d){return (c&&c.wallet!=null)?(+c.wallet||0):((d&&d.balance!=null)?(+d.balance||0):((d&&d.wallet)||[]).reduce((s,w)=>s+(+w.amount||0),0));}
function setSpyBalance(c,d,bal){bal=Math.max(0,+bal||0);if(c&&c.wallet!=null)c.wallet=+bal.toFixed(2);else if(d)d.balance=+bal.toFixed(2);}
function spyWxTransferOpen(id){const c=getC(id),d=S.spy[id]||getSpy(c);if(!c||!d)return;const bal=spyBalance(c,d),safeId=esc(String(id||''));openModal(`<h3>转给自己</h3><div class="hint">从${esc(c.remark||c.name)}的微信余额转出；会留下账单痕迹，ta之后可能发现。</div><div class="field"><label>转账金额</label><input id="spyWxTransferAmount" type="number" min="0.01" max="${bal.toFixed(2)}" step="0.01" inputmode="decimal" value="${Math.min(52,bal).toFixed(2)}"><small style="display:block;color:#888;margin-top:4px">当前余额约 ¥${bal.toFixed(2)}</small></div><div class="field"><label>转账备注（可留空）</label><input id="spyWxTransferNote" maxlength="40" placeholder="填写备注"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="spyWxTransferSubmit('${safeId}')">确认转给自己</button></div>`);}
function spyWxTransferSubmit(id){const amountEl=$('#spyWxTransferAmount'),noteEl=$('#spyWxTransferNote'),amount=Math.max(0,+String(amountEl&&amountEl.value||'').replace(/[^\d.]/g,'')||0),note=String(noteEl&&noteEl.value||'').trim().slice(0,40);if(amount<=0){toast('金额不对');return false;}closeModal();spyWxTransferDo(id,amount,note);return true;}
function spyWxTransferDo(id,amount,note){const c=getC(id),d=S.spy[id]||getSpy(c);if(!c||!d)return;const bal=spyBalance(c,d),actual=Math.min(bal,Math.max(0,+amount||0));
  if(actual<=0){toast('余额不够');return;}setSpyBalance(c,d,bal-actual);
  d.wallet=d.wallet||[];d.wallet.unshift({item:'微信转账给'+S.me.name+(note?'：'+note:''),amount:-actual,when:ymd(Date.now())+' '+hm()});d.wallet=d.wallet.slice(0,40);
  addBill('in',actual,'登录'+(c.remark||c.name)+'微信转给自己'+(note?'：'+note:''));c._meWxTransfers=c._meWxTransfers||[];
  c._meWxTransfers.unshift({id:uid(),ts:Date.now(),amount:actual,note:note||''});c._meWxTransfers=c._meWxTransfers.slice(0,20);
  save();render();toast('已转给自己 ¥'+actual.toFixed(2)+'，并退出微信');
  if(!c.blocked)setTimeout(()=>scheduleReply(id,'[系统：你刚在自己的微信钱包账单里发现：'+S.me.name+'登录过你的微信，并从你的余额里转给ta自己 ¥'+actual.toFixed(2)+(note?'，备注：'+note.slice(0,24):'')+'。这不是你主动转账，是ta登你微信转走后留下的账单痕迹。你现在自然来找ta反应：可以质问、吃醋、无奈、纵容、要解释或让ta还回来，按你人设来，别太长。]'),(80+Math.floor(Math.random()*90))*1000);}

