const _spyGrudgeFilters=Object.create(null);let _spyOrganizerDraft=null;
function spyOrganizerArg(v){return esc(JSON.stringify(String(v))).replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function spyTodoPage(id,d){const rows=d.todo&&d.todo.date===todayStr()&&Array.isArray(d.todo.items)?d.todo.items:[],done=rows.filter(x=>x.done).length,j=spyOrganizerArg(id),date=new Date(todayStr()+'T12:00:00'),label=isNaN(+date)?todayStr():`${date.getMonth()+1}月${date.getDate()}日 · 周${'日一二三四五六'[date.getDay()]}`;
 const section=(completed)=>{const list=rows.map((x,i)=>({x,i})).filter(({x})=>!!x.done===completed);return list.length?`<section class="so-tasks"><h3>${completed?'已完成':'待完成'} <small>${list.length}</small></h3><div class="so-timeline">${list.map(({x,i})=>`<article class="so-task ${completed?'is-done':''}"><button class="so-check" aria-label="${completed?'恢复':'完成'}行程" aria-pressed="${!!x.done}" onclick="spyTodoToggle(${j},${i})">${completed?'✓':''}</button><button class="so-task-content" onclick="spyOrganizerEditor('todo',${j},${i})"><span>${esc(x.text)}</span><time>${esc(x.time||'未定时间')}</time></button></article>`).join('')}</div></section>`:'';};
 return `<header class="so-today"><div><h1>今天</h1><p>${label}</p></div><div class="so-progress"><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="33"/><circle class="value" cx="40" cy="40" r="33" stroke-dasharray="${rows.length?done/rows.length*207.35:0} 207.35"/></svg><b>${done}/${rows.length}</b></div></header>${spyTodoOwnerRows(getC(id)).length?`<p class="so-editor-hint">${getC(id).proactive&&getC(id).proactive.enabled&&getC(id).proactive.serverPush?(d.todo.reportSyncPending?'日程正在同步后台，成功后锁屏也可到点报备。':'按手机时间到点，由角色自然报备；报备不等于完成。'):'后台报备需要开启该角色的服务器主动消息。'}</p>`:''}${section(false)}${section(true)}${rows.length?'':'<div class="so-empty"><h3>今天还没有日程</h3><p>添加一件要做的事，或刷新角色资料。</p></div>'}<button class="so-add" onclick="spyOrganizerEditor('todo',${j},-1)"><svg class="so-add-icon" viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><circle cx="10" cy="10" r="8"/><path d="M10 6v8M6 10h8"/></svg> 添加行程</button>`;}
function spyGrudgeFilter(id,filter){_spyGrudgeFilters[id]=filter;render();}
function spyGrudgeSec(id){const c=getC(id);if(!c)return '';const g=grudgesOf(c),undone=g.filter(x=>!x.done).length,j=spyOrganizerArg(id),filter=_spyGrudgeFilters[id]||'all',shown=g.map((x,i)=>({x,i})).filter(({x})=>filter==='all'||(filter==='done'?!!x.done:!x.done));
 return `<header class="so-grudge-heading"><div><h2>ta的记仇小本本</h2><span class="so-badge">${undone?undone+' 笔未消气':'都消气啦'}</span></div><button onclick="spyAddGrudge(${j})">＋ 记一笔</button></header><div class="so-tabs">${[['all','全部',g.length],['pending','未消气',undone],['done','已和好',g.length-undone]].map(([key,label,n])=>`<button class="${key===filter?'active':''}" onclick="spyGrudgeFilter(${j},'${key}')">${label} <span>${n}</span></button>`).join('')}</div><div class="so-grudges">${shown.length?shown.map(({x,i})=>`<article class="so-grudge ${x.done?'is-done':''}"><header><span class="so-badge">${x.done?'已和好':'未消气'}</span><time>${x.ts?esc(ymd(x.ts)):'时间未记录'}</time><button aria-label="编辑这笔记仇" onclick="spyOrganizerEditor('grudge',${j},${i})">···</button></header><button class="so-grudge-text" onclick="spyOrganizerEditor('grudge',${j},${i})">${esc(x.text)}</button><footer><small>${x.done?'这件事已经翻篇了':'这件事，ta还记着'}</small><button onclick="spyToggleGrudge(${j},${i})">${x.done?'重新记着 ↶':'标记已和好 ✓'}</button></footer></article>`).join(''):`<div class="so-empty"><svg viewBox="0 0 100 110" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M24 10h51q10 0 10 10v65L70 100H24q-8 0-8-9V19q0-9 8-9ZM70 100V86h15M9 29h15M9 48h15M9 67h15M9 86h15"/><path class="bookmark" d="M58 11v24l8-6 8 6V11"/></svg><h3>${g.length?'这里暂时没有记录':'小本本还是空的'}</h3><p>${g.length?'切换筛选，看看其他记录。':'ta暂时没记仇～'}</p>${g.length?'':`<button class="so-add" onclick="spyAddGrudge(${j})">＋ 记下第一笔</button>`}</div>`}</div>`;}
